refused_program.body:
set -eu
git fetch {upstream_remote}
mb=$(git merge-base HEAD {upstream_remote}/{upstream_branch})
git merge --no-commit --no-ff -X theirs {upstream_remote}/{upstream_branch} || true

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

git diff --name-only -z --diff-filter=M "$mb" HEAD | tr '\0' '\n' > "$tmp/local_paths"

while IFS= read -r path; do
  [ -n "$path" ] || continue
  if git ls-files -u -- "$path" | grep -q .; then
    git checkout --theirs -- "$path" 2>/dev/null || true
    git add -- "$path"
  fi
  [ -f "$path" ] || continue
  git cat-file -e "$mb:$path" 2>/dev/null || continue
  git cat-file -e "HEAD:$path" 2>/dev/null || continue
  git show "$mb:$path" > "$tmp/base"
  git show "HEAD:$path" > "$tmp/ours"
  git diff --no-index -U0 --no-color -- "$tmp/base" "$tmp/ours" > "$tmp/local_diff" 2>/dev/null || true
  awk '
    /^@@ / {
      split($2, hm, ",")
      anc = substr(hm[1], 2) + 0
      cnt = (length(hm) > 1 ? hm[2] + 0 : 1)
      keep = (cnt == 0)
      next
    }
    keep && /^\+/ && !/^\+\+\+/ { print anc "\t" substr($0, 2) }
  ' "$tmp/local_diff" > "$tmp/insertions"
  if [ ! -s "$tmp/insertions" ]; then
    continue
  fi
  cp -- "$path" "$tmp/merged"
  git diff --no-index -U0 --no-color -- "$tmp/base" "$tmp/merged" > "$tmp/merged_diff" 2>/dev/null || true
  awk '
    BEGIN { base_ptr = 1; merged_ptr = 1; i = 0 }
    FNR == NR {
      tab = index($0, "\t")
      if (tab == 0) next
      n++
      ia[n] = substr($0, 1, tab - 1) + 0
      it[n] = substr($0, tab + 1)
      next
    }
    /^@@ / {
      split($2, hm, ",")
      a = substr(hm[1], 2) + 0
      bc = (length(hm) > 1 ? hm[2] + 0 : 1)
      split($3, hn, ",")
      c = substr(hn[1], 2) + 0
      tc = (length(hn) > 1 ? hn[2] + 0 : 1)
      while (i < n && ia[i + 1] < a) {
        i++
        target[i] = merged_ptr + (ia[i] - base_ptr)
      }
      while (i < n && ia[i + 1] < a + bc) {
        i++
        target[i] = c - 1
      }
      base_ptr = a + bc
      merged_ptr = c + tc
      next
    }
    END {
      while (i < n) {
        i++
        target[i] = merged_ptr + (ia[i] - base_ptr)
      }
      for (k = 1; k <= n; k++) print target[k] "\t" it[k]
    }
  ' "$tmp/insertions" "$tmp/merged_diff" > "$tmp/targets"
  awk '
    FNR == NR {
      tab = index($0, "\t")
      if (tab == 0) next
      nt++
      ta[nt] = substr($0, 1, tab - 1) + 0
      tt[nt] = substr($0, tab + 1)
      next
    }
    { line[++n] = $0 }
    END {
      for (k = 1; k <= nt; k++) {
        dup[k] = 0
        for (j = 1; j <= n; j++) {
          if (line[j] == tt[k]) { dup[k] = 1; break }
        }
      }
      for (k = 1; k <= nt; k++) {
        if (!dup[k] && ta[k] <= 0) print tt[k]
      }
      for (j = 1; j <= n; j++) {
        print line[j]
        for (k = 1; k <= nt; k++) {
          if (!dup[k] && ta[k] == j) print tt[k]
        }
      }
      for (k = 1; k <= nt; k++) {
        if (!dup[k] && ta[k] > n) print tt[k]
      }
    }
  ' "$tmp/targets" "$path" > "$tmp/resolved"
  cp -- "$tmp/resolved" "$path"
  git add -- "$path"
done < "$tmp/local_paths"

git commit --no-edit
